import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import ThankYouPage from './components/ThankYouPage';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);

// Simple client-side routing logic
// If the path contains '/obrigado' OR the query param ?page=obrigado exists, show the Thank You page.
const path = window.location.pathname;
const search = window.location.search;
const showThankYou = path.includes('/obrigado') || search.includes('page=obrigado');

root.render(
  <React.StrictMode>
    {showThankYou ? <ThankYouPage /> : <App />}
  </React.StrictMode>
);
